PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?empresa WHERE {
  {
    SELECT ?empresa (SUM(?gasEmpresa) AS ?total) WHERE {
      {
        SELECT ?c (SUM(?g) AS ?gasEmpresa) WHERE {
          ?p a energia:ShaleProduction ;
             energia:declaredBy ?c ;
             energia:gas ?g .
        } GROUP BY ?c
      }
      {
        SELECT ?c (MIN(?n) AS ?nombre) WHERE {
          ?c energia:name ?n .
        } GROUP BY ?c
      }
      BIND(IF(CONTAINS(UCASE(STR(?nombre)), "PLUSPETROL"), "PLUSPETROL", STR(?nombre)) AS ?empresa)
    } GROUP BY ?empresa
  }
}
ORDER BY DESC(?total)
LIMIT 5
